<?php require 'config.php';auth();$cart=$_SESSION['cart']??[];if(!$cart)go('cart.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify();try{$db->beginTransaction();$s=$db->prepare('SELECT * FROM products WHERE active=1 AND id IN ('.implode(',',array_fill(0,count($cart),'?')).') FOR UPDATE');$s->execute(array_keys($cart));$items=$s->fetchAll();if(count($items)!==count($cart))throw new Exception('An item is unavailable.');$total=0;foreach($items as $p){$q=$cart[$p['id']];if(!is_int($q)||$q<1||$q>20)throw new Exception('Invalid quantity.');$total+=$p['price']*$q;}$s=$db->prepare('INSERT INTO orders(user_id,total) VALUES(?,?)');$s->execute([$_SESSION['id'],$total]);$order=$db->lastInsertId();$s=$db->prepare('INSERT INTO order_items(order_id,product_id,quantity,price) VALUES(?,?,?,?)');foreach($items as $p)$s->execute([$order,$p['id'],$cart[$p['id']],$p['price']]);$db->commit();unset($_SESSION['cart']);go('orders.php');}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error='Could not place order. Please review your cart.';}}head('Checkout');?><section class="form"><h1>Confirm order</h1><p>This is a demo; no payment is collected.</p><p><?=h($error)?></p><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><button>Place order</button></form></section><?php foot();?>
